class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        import bisect
        n = len(nums)
        vs = sorted(set(nums))
        M = len(vs)
        cb = [0] * (M + 1)
        sb = [0] * (M + 1)
        def upd(p, v, d):
            p += 1
            while p <= M:
                cb[p] += d; sb[p] += d * v
                p += p & (-p)
        def pref(b, p):
            s = 0; p += 1
            while p > 0:
                s += b[p]; p -= p & (-p)
            return s
        step = 1
        while step * 2 <= M:
            step *= 2
        def kth(c):
            p = 0
            while step:
                np_ = p + step
                if np_ <= M and cb[np_] < c:
                    p = np_; c -= cb[np_]
                step //= 2
            return vs[p]
        W = n - x + 1
        cost = [0] * W
        for i in range(x):
            upd(bisect.bisect_left(vs, nums[i]), nums[i], 1)
        def calc():
            med = kth((x + 1) // 2)
            pos = bisect.bisect_left(vs, med)
            L = pref(cb, pos - 1); SL = pref(sb, pos - 1)
            cm = pref(cb, pos) - L
            S = pref(sb, M - 1)
            return med * L - SL + (S - SL) - med * (x - L - cm)
        cost[0] = calc()
        for s in range(1, W):
            upd(bisect.bisect_left(vs, nums[s-1]), nums[s-1], -1)
            upd(bisect.bisect_left(vs, nums[s+x-1]), nums[s+x-1], 1)
            cost[s] = calc()
        INF = float('inf')
        prev = [0] * (W + 1)
        for _ in range(k):
            cur = [INF] * (W + 1)
            for s in range(W):
                cur[s + 1] = cur[s]
                if s - x >= 0 or True:
                    base = prev[s - x] if s - x >= 0 else 0
                    if _ == 0 or s - x >= 0:
                        cur[s + 1] = min(cur[s + 1], base + cost[s])
            prev = cur
        return prev[W]

