class Solution {
public:
    long long minOperations(vector<int>& nums, int x, int k) {
        int n = nums.size();
        vector<int> vs = nums;
        sort(vs.begin(), vs.end()); vs.erase(unique(vs.begin(), vs.end()), vs.end());
        int M = vs.size();
        vector<long long> cb(M + 1, 0), sb(M + 1, 0);
        auto upd = [&](int p, long long v, long long d) { for (++p; p <= M; p += p & -p) { cb[p] += d; sb[p] += d * v; } };
        auto pref = [&](vector<long long>& b, int p) { long long s = 0; for (++p; p > 0; p -= p & -p) s += b[p]; return s; };
        int step = 1; while (step * 2 <= M) step *= 2;
        auto kth = [&](long long c) { int p = 0; for (; step; step /= 2) { int np = p + step; if (np <= M && cb[np] < c) { p = np; c -= cb[np]; } } return vs[p]; };
        int W = n - x + 1;
        vector<long long> cost(W);
        auto add = [&](int v, int d) { upd(lower_bound(vs.begin(), vs.end(), v) - vs.begin(), v, d); };
        for (int i = 0; i < x; i++) add(nums[i], 1);
        auto calc = [&]() {
            long long med = kth((x + 1) / 2);
            int pos = lower_bound(vs.begin(), vs.end(), (int)med) - vs.begin();
            long long L = pref(cb, pos - 1), SL = pref(sb, pos - 1);
            long long cm = pref(cb, pos) - L, S = pref(sb, M - 1);
            return med * L - SL + (S - SL) - med * (x - L - cm);
        };
        cost[0] = calc();
        for (int s = 1; s < W; s++) { add(nums[s-1], -1); add(nums[s+x-1], 1); cost[s] = calc(); }
        const long long INF = LLONG_MAX / 2;
        vector<long long> prev(W + 1, 0), cur(W + 1);
        for (int j = 1; j <= k; j++) {
            cur[0] = INF;
            for (int s = 0; s < W; s++) {
                cur[s + 1] = cur[s];
                if (s - x >= 0 || j == 1) {
                    long long base = (s - x >= 0) ? prev[s - x + 1] : 0;
                    cur[s + 1] = min(cur[s + 1], base + cost[s]);
                }
            }
            prev = cur;
        }
        return prev[W];
    }
};

