class Solution {
    public long minOperations(int[] nums, int x, int k) {
        int n = nums.length;
        int[] tmp = nums.clone();
        Arrays.sort(tmp);
        int M = 0;
        for (int i = 0; i < n; i++) if (i == 0 || tmp[i] != tmp[i-1]) tmp[M++] = tmp[i];
        long[] cb = new long[M + 1], sb = new long[M + 1];
        java.util.function.BiConsumer<Integer,Integer>[] dummy = null;
        Runnable r = () -> {};
        // helpers as local classes
        class BIT {
            void upd(int p, long v, long d) { for (++p; p <= M; p += p & (-p)) { cb[p] += d; sb[p] += d * v; } }
            long pref(long[] b, int p) { long s = 0; for (++p; p > 0; p -= p & (-p)) s += b[p]; return s; }
            long kth(long c) { int p = 0, step = 1; while (step * 2 <= M) step *= 2; for (; step > 0; step /= 2) { int np = p + step; if (np <= M && cb[np] < c) { p = np; c -= cb[np]; } } return tmp[p]; }
        }
        BIT bit = new BIT();
        int W = n - x + 1;
        long[] cost = new long[W];
        java.util.HashMap<Integer,Integer> idOf = new java.util.HashMap<>();
        for (int i = 0; i < M; i++) idOf.put(tmp[i], i);
        for (int i = 0; i < x; i++) bit.upd(idOf.get(nums[i]), nums[i], 1);
        for (int s = 0; s < W; s++) {
            if (s > 0) { bit.upd(idOf.get(nums[s-1]), nums[s-1], -1); bit.upd(idOf.get(nums[s+x-1]), nums[s+x-1], 1); }
            long med = bit.kth((x + 1) / 2);
            int pos = idOf.get((int) med);
            long L = bit.pref(cb, pos - 1), SL = bit.pref(sb, pos - 1);
            long cm = bit.pref(cb, pos) - L, S = bit.pref(sb, M - 1);
            cost[s] = med * L - SL + (S - SL) - med * (x - L - cm);
        }
        long INF = Long.MAX_VALUE / 2;
        long[] prev = new long[W + 1], cur = new long[W + 1];
        Arrays.fill(prev, 0);
        for (int j = 1; j <= k; j++) {
            cur[0] = INF;
            for (int s = 0; s < W; s++) {
                cur[s + 1] = cur[s];
                long base = (s - x >= 0) ? prev[s - x + 1] : (j == 1 ? 0 : INF);
                if (base < INF) cur[s + 1] = Math.min(cur[s + 1], base + cost[s]);
            }
            prev = cur.clone();
        }
        return prev[W];
    }
}

