var minOperations = function(nums, x, k) {
    const n = nums.length;
    const vs = [...new Set(nums)].sort((a, b) => a - b);
    const M = vs.length;
    const cb = new Array(M + 1).fill(0), sb = new Array(M + 1).fill(0);
    const upd = (p, v, d) => { for (++p; p <= M; p += p & (-p)) { cb[p] += d; sb[p] += d * v; } };
    const pref = (b, p) => { let s = 0; for (++p; p > 0; p -= p & (-p)) s += b[p]; return s; };
    let step = 1; while (step * 2 <= M) step *= 2;
    const kth = c => { let p = 0; for (; step > 0; step = Math.floor(step / 2)) { const np = p + step; if (np <= M && cb[np] < c) { p = np; c -= cb[np]; } } return vs[p]; };
    const id = new Map(vs.forEach ? [] : []);
    const idx = new Map(); vs.forEach((v, i) => idx.set(v, i));
    const W = n - x + 1, cost = new Array(W);
    for (let i = 0; i < x; i++) upd(idx.get(nums[i]), nums[i], 1);
    for (let s = 0; s < W; s++) {
        if (s > 0) { upd(idx.get(nums[s-1]), nums[s-1], -1); upd(idx.get(nums[s+x-1]), nums[s+x-1], 1); }
        const med = kth((x + 1) >> 1), pos = idx.get(med);
        const L = pref(cb, pos - 1), SL = pref(sb, pos - 1);
        const cm = pref(cb, pos) - L, S = pref(sb, M - 1);
        cost[s] = med * L - SL + (S - SL) - med * (x - L - cm);
    }
    const INF = Infinity;
    let prev = new Array(W + 1).fill(0);
    for (let j = 1; j <= k; j++) {
        const cur = new Array(W + 1).fill(INF);
        for (let s = 0; s < W; s++) {
            cur[s + 1] = cur[s];
            const base = (s - x >= 0) ? prev[s - x + 1] : (j === 1 ? 0 : INF);
            if (base < INF) cur[s + 1] = Math.min(cur[s + 1], base + cost[s]);
        }
        prev = cur;
    }
    return prev[W];
};
